    AUTH_MODES = ("uri", "x509", "aws_service_credential")
    HTTP_TIMEOUT_SECONDS = 30
    # Refresh AWS keys this long before they expire. Unity Catalog can hand back
    # keys that were issued earlier, so the remaining lifetime is often well under
    # an hour; the refresh decision must be based on the reported expiry time.
    DEFAULT_REFRESH_MARGIN_SECONDS = 600


    class AwsKeys:  # pylint: disable=too-few-public-methods
        """Temporary AWS keys and their expiry (epoch seconds)."""

        def __init__(self, access_key_id: str, secret_access_key: str, session_token: str,
                     expires_at: float):
            self.access_key_id = access_key_id
            self.secret_access_key = secret_access_key
            self.session_token = session_token
            self.expires_at = expires_at

        def needs_refresh(self, margin_seconds: int, now: Optional[float] = None) -> bool:
            return (now if now is not None else time.time()) >= self.expires_at - margin_seconds


    class UcServiceCredentialProvider:
        """Fetch temporary AWS keys for a Unity Catalog service credential.

        Authenticates to the workspace as a service principal with OAuth
        machine-to-machine (client credentials). The service principal needs the
        ``workspace-access`` entitlement and ``ACCESS`` on the service credential.
        """

        def __init__(self, host: str, client_id: str, client_secret: str, credential_name: str,
                     session: Optional[requests.Session] = None):
            if not host:
                raise ValueError("auth_mode=aws_service_credential requires 'databricks_host'")
            if not client_id or not client_secret:
                raise ValueError(
                    "auth_mode=aws_service_credential requires 'databricks_client_id' and "
                    "'databricks_client_secret' (a service principal OAuth secret)"
                )
            if not credential_name:
                raise ValueError("auth_mode=aws_service_credential requires 'aws_service_credential'")
            self.host = host.rstrip("/")
            if not self.host.startswith("https://"):
                self.host = "https://" + self.host.removeprefix("http://")
            self.client_id = client_id
            self.client_secret = client_secret
            self.credential_name = credential_name
            self._session = session or requests.Session()
            self._token: Optional[str] = None
            self._token_expires_at = 0.0

        def _oauth_token(self) -> str:
            if self._token and time.time() < self._token_expires_at - 60:
                return self._token
            resp = self._session.post(
                f"{self.host}/oidc/v1/token",
                data={"grant_type": "client_credentials", "scope": "all-apis"},
                auth=(self.client_id, self.client_secret),
                timeout=HTTP_TIMEOUT_SECONDS,
            )
            if resp.status_code != 200:
                raise RuntimeError(
                    f"OAuth token request to {self.host} failed with HTTP {resp.status_code}: "
                    f"{resp.text[:300]}"
                )
            body = resp.json()
            self._token = body["access_token"]
            self._token_expires_at = time.time() + int(body.get("expires_in", 3600))
            return self._token

        def fetch(self) -> AwsKeys:
            resp = self._session.post(
                f"{self.host}/api/2.1/unity-catalog/temporary-service-credentials",
                json={"credential_name": self.credential_name},
                headers={"Authorization": f"Bearer {self._oauth_token()}"},
                timeout=HTTP_TIMEOUT_SECONDS,
            )
            if resp.status_code != 200:
                hint = ""
                if resp.status_code == 403 and "entitlement" in resp.text:
                    hint = " (grant the service principal the 'workspace-access' entitlement)"
                raise RuntimeError(
                    f"temporary-service-credentials for '{self.credential_name}' failed with HTTP "
                    f"{resp.status_code}: {resp.text[:300]}{hint}"
                )
            body = resp.json()
            aws = body.get("aws_temp_credentials")
            if not aws:
                raise RuntimeError(
                    f"service credential '{self.credential_name}' did not return AWS credentials; "
                    "it must be an AWS IAM role service credential"
                )
            return AwsKeys(
                aws["access_key_id"],
                aws["secret_access_key"],
                aws["session_token"],
                int(body["expiration_time"]) / 1000,
            )


    def _write_private_file(content: str, suffix: str) -> str:
        fd, path = tempfile.mkstemp(prefix="lakeflow_mongodb_", suffix=suffix)
        try:
            os.write(fd, content.encode("utf-8"))
        finally:
            os.close(fd)
        os.chmod(path, 0o600)
        return path


    class MongoClientFactory:
        """Build ``MongoClient`` instances and rebuild them when keys expire.

        The factory is created on the driver from the connector options and is
        pickled to Python workers, so it never holds a live client or socket.
        """

        def __init__(self, options: dict[str, str], client_kwargs: Optional[dict] = None):
            self.uri = options.get("connection_uri") or ""
            if not self.uri:
                raise ValueError("MongoDB connector requires the 'connection_uri' connection parameter")
            self.auth_mode = options.get("auth_mode") or "uri"
            if self.auth_mode not in AUTH_MODES:
                raise ValueError(
                    f"'auth_mode' must be one of {', '.join(AUTH_MODES)}; got {self.auth_mode!r}"
                )
            self.options = {k: v for k, v in options.items() if v is not None}
            self.client_kwargs = dict(client_kwargs or {})
            self.refresh_margin = int(
                options.get("aws_refresh_margin_seconds") or DEFAULT_REFRESH_MARGIN_SECONDS
            )
            self._lock = threading.Lock()
            self._provider: Optional[UcServiceCredentialProvider] = None
            self._keys: Optional[AwsKeys] = None
            self._files: dict[str, str] = {}
            if self.auth_mode == "x509" and not options.get("tls_certificate_key_pem"):
                raise ValueError("auth_mode=x509 requires 'tls_certificate_key_pem'")
            if self.auth_mode == "aws_service_credential":
                # Validate eagerly so configuration errors surface at pipeline start.
                self._make_provider()

        def __getstate__(self):
            state = self.__dict__.copy()
            state["_lock"] = None
            state["_provider"] = None
            state["_keys"] = None
            state["_files"] = {}
            return state

        def __setstate__(self, state):
            self.__dict__.update(state)
            self._lock = threading.Lock()

        def _make_provider(self) -> UcServiceCredentialProvider:
            if self._provider is None:
                self._provider = UcServiceCredentialProvider(
                    self.options.get("databricks_host", ""),
                    self.options.get("databricks_client_id", ""),
                    self.options.get("databricks_client_secret", ""),
                    self.options.get("aws_service_credential", ""),
                )
            return self._provider

        def _file_option(self, key: str, suffix: str) -> Optional[str]:
            pem = self.options.get(key)
            if not pem:
                return None
            path = self._files.get(key)
            if not path or not os.path.exists(path):
                path = _write_private_file(pem, suffix)
                self._files[key] = path
            return path

        def credentials_expire_soon(self) -> bool:
            """True when a client built earlier must be replaced (new AWS keys)."""
            if self.auth_mode != "aws_service_credential":
                return False
            with self._lock:
                return self._keys is None or self._keys.needs_refresh(self.refresh_margin)

        def build_kwargs(self) -> dict[str, Any]:
            kwargs: dict[str, Any] = {
                "appname": "lakeflow-community-connector-mongodb",
                # Fail fast with a clear error instead of hanging the micro-batch.
                "serverSelectionTimeoutMS": 30000,
                # Keep the first undecodable byte sequence from silently turning
                # into replacement characters: strict is the default, ``replace``
                # is opt-in through the ``unicode_decode_error_handler`` option.
                "unicode_decode_error_handler": self.options.get(
                    "unicode_decode_error_handler"
                ) or "strict",
                "tz_aware": True,
            }
            kwargs.update(self.client_kwargs)
            ca = self._file_option("tls_ca_pem", ".pem")
            if ca:
                kwargs["tlsCAFile"] = ca
            if self.auth_mode == "x509":
                kwargs["tlsCertificateKeyFile"] = self._file_option("tls_certificate_key_pem", ".pem")
                kwargs["authMechanism"] = "MONGODB-X509"
                kwargs["tls"] = True
            elif self.auth_mode == "aws_service_credential":
                with self._lock:
                    if self._keys is None or self._keys.needs_refresh(self.refresh_margin):
                        self._keys = self._make_provider().fetch()
                    keys = self._keys
                kwargs["authMechanism"] = "MONGODB-AWS"
                kwargs["authSource"] = "$external"
                kwargs["username"] = keys.access_key_id
                kwargs["password"] = keys.secret_access_key
                # Passed as a dict, not in the URI: the token can contain characters
                # that are not safe inside authMechanismProperties.
                kwargs["authMechanismProperties"] = {"AWS_SESSION_TOKEN": keys.session_token}
            return kwargs

        def create(self):
            import pymongo  # pylint: disable=import-outside-toplevel

            return pymongo.MongoClient(self.uri, **self.build_kwargs())


    ########################################################
    # src/databricks/labs/community_connector/sources/mongodb/mongodb_schemas.py
    ########################################################

    DOCUMENT_FORMATS = ("variant", "string")

    PRIMARY_KEY = "_id"
    CURSOR_FIELD = "_cdc_sequence"


    def table_schema(document_format: str = "variant") -> StructType:
        document_type = VariantType() if document_format == "variant" else StringType()
        return StructType(
            [
                StructField("_id", StringType(), False),
                StructField("document", document_type, True),
                StructField("_cdc_operation", StringType(), False),
                StructField("_cdc_sequence", StringType(), False),
                StructField("_cdc_cluster_time", TimestampType(), True),
                StructField("_cdc_wall_time", TimestampType(), True),
                StructField("_cdc_namespace", StringType(), False),
            ]
        )


    ########################################################
    # src/databricks/labs/community_connector/sources/mongodb/mongodb_utils.py
    ########################################################

    CANONICAL = JSONOptions(json_mode=JSONMode.CANONICAL, tz_aware=True, tzinfo=timezone.utc)
    # Relaxed Extended JSON reads naturally (numbers stay numbers, dates become
    # {"$date": "2024-01-01T00:00:00Z"}) and is what we put into the document column.
    RELAXED = JSONOptions(json_mode=JSONMode.RELAXED, tz_aware=True, tzinfo=timezone.utc)

    OFFSET_VERSION = 1


    def dumps(value: Any, options: JSONOptions = RELAXED) -> str:
        """Serialize a BSON value to Extended JSON without escaping non-ASCII text.

        ``ensure_ascii=False`` keeps multibyte text (Japanese, emoji, combining
        characters) as literal UTF-8 instead of ``\\uXXXX`` escapes, so the
        string column is readable and byte-for-byte equal to the source text.
        """
        return json_util.dumps(value, json_options=options, ensure_ascii=False, separators=(",", ":"))


    def loads(text: str, options: JSONOptions = CANONICAL) -> Any:
        """Parse Extended JSON produced by :func:`dumps`."""
        return json_util.loads(text, json_options=options)


    def encode_id(value: Any) -> str:
        """Encode a document ``_id`` into a string primary key.

        - ``ObjectId`` (the default ``_id`` type) becomes its 24-char hex string.
        - Every other type becomes canonical Extended JSON. A string ``_id`` is
          therefore JSON-quoted (``"abc"``), so it can never collide with an
          ObjectId hex string. Numbers keep their BSON type
          (``{"$numberInt": "7"}``), which is stable because MongoDB returns an
          ``_id`` with the type it was stored with.
        """
        if isinstance(value, ObjectId):
            return str(value)
        return dumps(value, CANONICAL)


    def decode_id(text: str) -> Any:
        """Inverse of :func:`encode_id`."""
        if len(text) == 24 and ObjectId.is_valid(text) and not text.startswith('"'):
            return ObjectId(text)
        return loads(text, CANONICAL)


    def timestamp_to_datetime(ts: Optional[Timestamp]) -> Optional[datetime]:
        """Convert a BSON ``Timestamp`` (cluster time) to an aware UTC datetime."""
        if ts is None:
            return None
        return datetime.fromtimestamp(ts.time, tz=timezone.utc)


    def to_utc(dt: Optional[datetime]) -> Optional[datetime]:
        """Normalize a datetime returned by PyMongo to aware UTC."""
        if dt is None:
            return None
        if dt.tzinfo is None:
            return dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)


    def token_data(token: Optional[dict]) -> Optional[str]:
        """Return the hex ``_data`` of a resume token (comparable as a string)."""
        if not token:
            return None
        data = token.get("_data")
        if not isinstance(data, str):
            raise ValueError(f"unsupported resume token format: {token!r}")
        return data


    def parse_bool(value: Optional[str], default: bool) -> bool:
        if value is None or value == "":
            return default
        lowered = str(value).strip().lower()
        if lowered in ("true", "1", "yes", "y"):
            return True
        if lowered in ("false", "0", "no", "n"):
            return False
        raise ValueError(f"expected a boolean, got {value!r}")


    def parse_int(value: Optional[str], default: int, name: str, minimum: int = 1) -> int:
        if value is None or value == "":
            return default
        try:
            parsed = int(value)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"option '{name}' must be an integer, got {value!r}") from exc
        if parsed < minimum:
            raise ValueError(f"option '{name}' must be >= {minimum}, got {parsed}")
        return parsed


    def parse_choice(value: Optional[str], default: str, name: str, choices: tuple[str, ...]) -> str:
        if value is None or value == "":
            return default
        if value not in choices:
            raise ValueError(f"option '{name}' must be one of {', '.join(choices)}; got {value!r}")
        return value


    ########################################################
    # src/databricks/labs/community_connector/sources/mongodb/mongodb.py
    ########################################################

    INGESTION_TYPES = ("cdc_with_deletes", "cdc", "append", "snapshot")
    START_MODES = ("snapshot", "latest", "timestamp")
    FULL_DOCUMENT_MODES = ("updateLookup", "whenAvailable", "required")
    SYSTEM_DATABASES = ("admin", "config", "local")

    # Change stream events that end the stream for a collection. They are always
    # matched so the connector fails loudly instead of silently stopping.
    TERMINAL_EVENTS = ("drop", "rename", "dropDatabase", "invalidate")
    UPSERT_EVENTS = ("insert", "update", "replace")
    DELETE_EVENTS = ("delete",)

    DEFAULT_MAX_RECORDS_PER_BATCH = 10_000
    DEFAULT_SNAPSHOT_BATCH_SIZE = 10_000
    DEFAULT_MAX_AWAIT_MS = 1_000
    DEFAULT_DELETE_LOOKBACK_SECONDS = 86_400
    DEFAULT_IDLE_ADVANCE_SECONDS = 300
    CLOCK_SKEW_SECONDS = 5
    MIN_LOOKBACK_SECONDS = 60
    SNAPSHOT_SEQUENCE = "0"
    REPLAY_MAX_EMPTY_POLLS = 30

    # MongoDB server error codes
    CHANGE_STREAM_HISTORY_LOST = 286
    CHANGE_STREAM_FATAL_ERROR = 280
    CHANGE_STREAM_NOT_SUPPORTED = 40573  # standalone server

    TABLE_OPTION_KEYS = (
        "database",
        "collection",
        "ingestion_type",
        "start_mode",
        "start_at_operation_time",
        "full_document",
        "document_format",
        "max_records_per_batch",
        "snapshot_batch_size",
        "max_await_time_ms",
        "delete_lookback_seconds",
        "idle_advance_seconds",
    )


    class _TableConfig:  # pylint: disable=too-many-instance-attributes,too-few-public-methods
        """Validated per-table options."""

        def __init__(self, connector: "MongodbLakeflowConnect", table_name: str,
                     table_options: dict[str, str]):
            opts = {**connector.default_table_options, **(table_options or {})}
            database = opts.get("database") or connector.default_database
            # ``collection`` lets the table name be an ASCII alias. The pipeline
            # builds view names from the table name, and those must be plain
            # identifiers, so collections with multibyte or special characters in
            # their name are ingested as source_table=<alias> + collection=<name>.
            collection = opts.get("collection") or table_name
            if not database:
                # Fall back to "<db>.<collection>" only when no database is configured.
                # Collection names may contain dots, so the explicit option is preferred.
                if "." not in table_name:
                    raise ValueError(
                        f"table '{table_name}': set the 'database' table option (or the "
                        "'database' connection parameter), or name the table '<database>.<collection>'"
                    )
                database, collection = collection.split(".", 1)
            self.database = database
            self.collection = collection
            self.namespace = f"{database}.{collection}"
            self.ingestion_type = parse_choice(
                opts.get("ingestion_type"), "cdc_with_deletes", "ingestion_type", INGESTION_TYPES
            )
            self.start_mode = parse_choice(opts.get("start_mode"), "snapshot", "start_mode", START_MODES)
            self.start_at_operation_time = opts.get("start_at_operation_time")
            if self.start_mode == "timestamp" and not self.start_at_operation_time:
                raise ValueError("start_mode=timestamp requires 'start_at_operation_time' (epoch seconds)")
            self.full_document = parse_choice(
                opts.get("full_document"), "updateLookup", "full_document", FULL_DOCUMENT_MODES
            )
            self.document_format = parse_choice(
                opts.get("document_format"), "variant", "document_format", DOCUMENT_FORMATS
            )
            self.max_records = parse_int(
                opts.get("max_records_per_batch"), DEFAULT_MAX_RECORDS_PER_BATCH, "max_records_per_batch"
            )
            self.snapshot_batch_size = parse_int(
                opts.get("snapshot_batch_size"), DEFAULT_SNAPSHOT_BATCH_SIZE, "snapshot_batch_size"
            )
            self.max_await_ms = parse_int(
                opts.get("max_await_time_ms"), DEFAULT_MAX_AWAIT_MS, "max_await_time_ms"
            )
            self.delete_lookback = parse_int(
                opts.get("delete_lookback_seconds"), DEFAULT_DELETE_LOOKBACK_SECONDS,
                "delete_lookback_seconds", minimum=0
            )
            self.idle_advance = parse_int(
                opts.get("idle_advance_seconds"), DEFAULT_IDLE_ADVANCE_SECONDS,
                "idle_advance_seconds", minimum=0
            )


    class MongodbLakeflowConnect(LakeflowConnect, SupportsNamespaces):
        """Lakeflow Connect implementation for MongoDB (replica sets and sharded clusters)."""

        def __init__(self, options: dict[str, str]) -> None:
            super().__init__(options)
            self._factory = MongoClientFactory(options)
            self.default_database = options.get("database") or None
            self.default_table_options = {
                k: v for k, v in options.items() if k in TABLE_OPTION_KEYS and k != "database"
            }
            self._client = None
            # Upper bound (cluster time) for change events read in the current
            # trigger, per (namespace, flow). See _read_stream.
            self._caps: dict[tuple[str, str], Timestamp] = {}
            self._known: set[str] = set()

        # The connector is pickled to Python workers: never ship a live client.
        def __getstate__(self):
            state = self.__dict__.copy()
            state["_client"] = None
            state["_caps"] = {}
            state["_known"] = set()
            return state

        def __setstate__(self, state):
            self.__dict__.update(state)

        # ------------------------------------------------------------------ client

        def _get_client(self):
            if self._client is not None and self._factory.credentials_expire_soon():
                # New temporary AWS keys: the old client keeps authenticated sockets,
                # but any reconnect would fail once the keys expire.
                self._client.close()
                self._client = None
            if self._client is None:
                self._client = self._factory.create()
            return self._client

        def _collection(self, cfg: _TableConfig):
            return self._get_client()[cfg.database][cfg.collection]

        @staticmethod
        def _now() -> Timestamp:
            """The current time as a cluster-time bound.

            Taken from the local clock rather than from the server: some managed
            tiers (for example Atlas shared clusters) do not return
            ``operationTime``. The value only bounds how far one trigger reads and
            where the delete flow starts. It is rounded up and padded by
            ``CLOCK_SKEW_SECONDS`` so that every change made before the trigger
            started is read in that trigger, even if the server clock runs ahead.
            """
            return Timestamp(int(time.time()) + 1 + CLOCK_SKEW_SECONDS, 0)

        # --------------------------------------------------------------- catalog

        def list_namespaces(self, prefix: Optional[list[str]] = None) -> list[list[str]]:
            if prefix:
                return []  # databases have no child namespaces
            if self.default_database:
                return [[self.default_database]]
            names = self._get_client().list_database_names()
            return [[n] for n in names if n not in SYSTEM_DATABASES]

        def list_tables_in_namespace(self, namespace: list[str]) -> list[str]:
            if len(namespace) != 1:
                return []
            return self._list_collections(namespace[0])

        def _list_collections(self, database: str) -> list[str]:
            db = self._get_client()[database]
            # Views and time series collections cannot be watched by a change stream.
            cursor = db.list_collections(filter={"type": "collection"}, authorizedCollections=True,
                                         nameOnly=True)
            return sorted(c["name"] for c in cursor if not c["name"].startswith("system."))

        def list_tables(self) -> list[str]:
            if self.default_database:
                return self._list_collections(self.default_database)
            tables = []
            for (database,) in self.list_namespaces():
                tables.extend(f"{database}.{c}" for c in self._list_collections(database))
            return tables

        def _config(self, table_name: str, table_options: dict[str, str]) -> _TableConfig:
            cfg = _TableConfig(self, table_name, table_options)
            if cfg.namespace not in self._known:
                found = list(self._get_client()[cfg.database].list_collections(
                    filter={"name": cfg.collection}, authorizedCollections=True, nameOnly=True))
                if not found:
                    raise ValueError(
                        f"collection '{cfg.collection}' does not exist in database '{cfg.database}' "
                        "(or the user is not allowed to list it)"
                    )
                if found[0].get("type", "collection") != "collection":
                    raise ValueError(
                        f"'{cfg.namespace}' is a {found[0].get('type')}; only regular collections "
                        "have a change stream"
                    )
                self._known.add(cfg.namespace)
            return cfg

        def get_table_schema(self, table_name: str, table_options: dict[str, str]) -> StructType:
            cfg = self._config(table_name, table_options)
            return table_schema(cfg.document_format)

        def read_table_metadata(self, table_name: str, table_options: dict[str, str]) -> dict:
            cfg = self._config(table_name, table_options)
            if cfg.ingestion_type == "append":
                return {"cursor_field": CURSOR_FIELD, "ingestion_type": "append"}
            return {
                "primary_keys": [PRIMARY_KEY],
                "cursor_field": CURSOR_FIELD,
                "ingestion_type": cfg.ingestion_type,
            }

        # ------------------------------------------------------------------ reads

        def read_table(
            self, table_name: str, start_offset: dict, table_options: dict[str, str]
        ) -> tuple[Iterator[dict], dict]:
            cfg = self._config(table_name, table_options)
            if cfg.ingestion_type == "snapshot":
                return self._read_full_snapshot(cfg), None
            events = UPSERT_EVENTS + (DELETE_EVENTS if cfg.ingestion_type == "append" else ())
            return self._read_incremental(cfg, start_offset or {}, "upsert", events)

        def read_table_deletes(
            self, table_name: str, start_offset: dict, table_options: dict[str, str]
        ) -> tuple[Iterator[dict], dict]:
            cfg = self._config(table_name, table_options)
            return self._read_incremental(cfg, start_offset or {}, "delete", DELETE_EVENTS)

        def read_table_range(self, table_name: str, start_offset: dict, end_offset: dict,
                             table_options: dict[str, str], deletes: bool = False) -> Iterator[dict]:
            """Re-read exactly the batch ``(start_offset, end_offset]``.

            Used by :class:`MongodbStreamReader` when Spark replays a batch that was
            planned but not committed (after a restart). The generic reader re-reads
            from ``start_offset`` without a bound, which in ``append`` mode can write
            events of the next batch twice.
            """
            cfg = self._config(table_name, table_options)
            if cfg.ingestion_type == "snapshot":
                return self._read_full_snapshot(cfg)
            flow = "delete" if deletes else "upsert"
            if deletes:
                events = DELETE_EVENTS
            else:
                events = UPSERT_EVENTS + (DELETE_EVENTS if cfg.ingestion_type == "append" else ())
            records, _ = self._read_incremental(cfg, start_offset or {}, flow, events, end=end_offset)
            return records

        def _read_incremental(self, cfg: _TableConfig, start: dict, flow: str,
                              events: tuple[str, ...],
                              end: Optional[dict] = None) -> tuple[Iterator[dict], dict]:
            if not start:
                if end is not None:
                    return iter([]), end  # the first batch only fixes the starting point
                return iter([]), self._initial_offset(cfg, flow)
            self._check_offset(cfg, start)
            if start["phase"] == "snapshot":
                return self._read_snapshot_page(cfg, start, end)
            return self._read_stream(cfg, start, flow, events, end)

        def _check_offset(self, cfg: _TableConfig, offset: dict) -> None:
            if offset.get("v") != OFFSET_VERSION:
                raise ValueError(f"unsupported offset version in {offset!r}; run a full refresh")
            if offset.get("ns") != cfg.namespace:
                raise ValueError(
                    f"offset belongs to '{offset.get('ns')}' but the table now reads '{cfg.namespace}'. "
                    "Changing the source collection of a table needs a full refresh."
                )

        def _offset(self, cfg: _TableConfig, phase: str, token: str, **extra: Any) -> dict:
            return {"v": OFFSET_VERSION, "ns": cfg.namespace, "phase": phase, "token": token, **extra}

        def _current_token(self, cfg: _TableConfig) -> str:
            """A resume token for 'now', without consuming any event.

            The stream matches nothing, so the token returned is the server's
            post-batch resume token: every change up to it has been scanned and
            none was skipped by consuming it here.
            """
            import pymongo.errors  # pylint: disable=import-outside-toplevel

            try:
                with self._collection(cfg).watch(pipeline=[{"$match": {"_lakeflow_never": True}}],
                                                 max_await_time_ms=1) as stream:
                    stream.try_next()
                    return token_data(stream.resume_token)
            except pymongo.errors.OperationFailure as exc:
                if exc.code == CHANGE_STREAM_NOT_SUPPORTED:
                    raise RuntimeError(
                        "Change streams need a replica set or a sharded cluster; standalone servers "
                        "are not supported. Use ingestion_type=snapshot for a standalone server."
                    ) from exc
                raise

        def _initial_offset(self, cfg: _TableConfig, flow: str) -> dict:
            if cfg.start_mode == "timestamp":
                # Resolved by the first stream read (start_at_operation_time).
                return self._offset(cfg, "stream", None, start_at=int(float(cfg.start_at_operation_time)))
            if flow == "delete":
                # The delete flow is a separate stream that starts slightly after the
                # upsert flow takes its snapshot token. Start it a little in the past:
                # deletes older than the snapshot carry a smaller sequence than the
                # snapshot rows, so apply_changes ignores them, and none in the gap
                # between the two flows is lost.
                if cfg.delete_lookback == 0:
                    return self._offset(cfg, "stream", self._current_token(cfg))
                now = self._now()
                return self._offset(cfg, "stream", None, start_at=max(now.time - cfg.delete_lookback, 1),
                                    lookback=True)
            token = self._current_token(cfg)
            if cfg.start_mode == "latest":
                return self._offset(cfg, "stream", token)
            return self._offset(cfg, "snapshot", token, last_id=None)

        def _read_snapshot_page(self, cfg: _TableConfig, start: dict,
                                end: Optional[dict] = None) -> tuple[Iterator[dict], dict]:
            limit = min(cfg.max_records, cfg.snapshot_batch_size)
            conditions = []
            if start.get("last_id") is not None:
                last = loads(start["last_id"], CANONICAL)
                # $expr compares across BSON types in MongoDB's sort order, so a
                # collection whose _id mixes ObjectId, strings and numbers is paged
                # without skipping a type (a plain {$gt} only matches the same type).
                conditions.append({"$gt": ["$_id", {"$literal": last}]})
            if end is not None:
                # Replay: stop at the last _id of the original page (also for the
                # final page, whose end offset is already in the stream phase).
                end_id = end.get("last_id") if end.get("phase") == "snapshot" else end.get("snapshot_last_id")
                if end_id is None:
                    return iter([]), end
                conditions.append({"$lte": ["$_id", {"$literal": loads(end_id, CANONICAL)}]})
                limit = 0
            query = {"$expr": {"$and": conditions}} if conditions else {}
            docs = self._guard_decode(
                cfg, lambda: list(self._collection(cfg).find(query).sort("_id", 1).limit(limit))
            )
            if end is not None:
                return iter([self._snapshot_row(cfg, d, start["token"]) for d in docs]), end
            rows = [self._snapshot_row(cfg, d, start["token"]) for d in docs]
            if len(docs) < limit:
                # Snapshot done: stream from the token taken before the snapshot began.
                # The last _id is kept so that a replay of this page can stop there.
                final_id = dumps(docs[-1]["_id"], CANONICAL) if docs else start.get("last_id")
                return iter(rows), self._offset(cfg, "stream", start["token"], snapshot_last_id=final_id)
            last_id = dumps(docs[-1]["_id"], CANONICAL)
            return iter(rows), self._offset(cfg, "snapshot", start["token"], last_id=last_id)

        def _read_full_snapshot(self, cfg: _TableConfig) -> Iterator[dict]:
            # apply_changes_from_snapshot does not order by _cdc_sequence, and this
            # mode must work without change streams (standalone servers, users
            # without the changeStream privilege), so no resume token is taken.
            token = SNAPSHOT_SEQUENCE
            cursor = self._collection(cfg).find({}).sort("_id", 1).batch_size(cfg.snapshot_batch_size)
            try:
                for doc in cursor:
                    yield self._snapshot_row(cfg, doc, token)
            except (InvalidBSON, UnicodeDecodeError) as exc:
                raise self._decode_error(cfg, exc) from exc

        def _snapshot_row(self, cfg: _TableConfig, doc: dict, token: str) -> dict:
            return {
                "_id": encode_id(doc["_id"]),
                "document": dumps(doc),
                "_cdc_operation": "snapshot",
                "_cdc_sequence": token,
                "_cdc_cluster_time": None,
                "_cdc_wall_time": None,
                "_cdc_namespace": cfg.namespace,
            }

        def _read_stream(self, cfg: _TableConfig, start: dict, flow: str,
                         events: tuple[str, ...],
                         end: Optional[dict] = None) -> tuple[Iterator[dict], dict]:
            """Read one micro-batch of change events after ``start``.

            With ``end`` (a replay of a batch that was planned but not committed),
            read exactly the events up to and including ``end``, so the replayed
            batch has the same rows as the original one.
            """
            import pymongo.errors  # pylint: disable=import-outside-toplevel

            if end is not None and (end.get("phase") != "stream" or not end.get("token")
                                    or end.get("idle") or end.get("token") == start.get("token")):
                return iter([]), end  # the batch had no events
            cap_key = (cfg.namespace, flow)
            cap = self._caps.get(cap_key)
            if cap is None:
                # Read only changes that existed when this trigger started, so that
                # Trigger.AvailableNow terminates even under constant writes.
                cap = self._caps[cap_key] = self._now()

            pipeline = [{"$match": {"operationType": {"$in": list(events + TERMINAL_EVENTS)}}}]
            watch_kwargs: dict[str, Any] = {
                "pipeline": pipeline,
                "max_await_time_ms": cfg.max_await_ms,
                "batch_size": min(cfg.max_records, 1000),
            }
            if start.get("token"):
                watch_kwargs["resume_after"] = {"_data": start["token"]}
            else:
                watch_kwargs["start_at_operation_time"] = Timestamp(int(start["start_at"]), 0)
            if flow == "upsert":
                watch_kwargs["full_document"] = cfg.full_document

            rows: list[dict] = []
            last_token: Optional[str] = None
            drained = False
            pbrt: Optional[str] = None
            empty_polls = 0
            try:
                with self._collection(cfg).watch(**watch_kwargs) as stream:
                    while end is not None or len(rows) < cfg.max_records:
                        event = stream.try_next()
                        if event is None:
                            empty_polls += 1
                            if end is not None and stream.alive and empty_polls < REPLAY_MAX_EMPTY_POLLS:
                                continue  # replay: the events up to `end` exist; keep polling
                            drained = True
                            pbrt = token_data(stream.resume_token)
                            break
                        token = token_data(event["_id"])
                        if end is not None:
                            if token > end["token"]:
                                break
                        elif event.get("clusterTime") and event["clusterTime"] > cap:
                            break  # newer than this trigger; read it next time
                        self._raise_if_terminal(cfg, event)
                        last_token = token
                        row = self._change_row(cfg, event, flow)
                        if row is not None:
                            rows.append(row)
                        if end is not None and token == end["token"]:
                            break
            except pymongo.errors.OperationFailure as exc:
                if (exc.code == CHANGE_STREAM_HISTORY_LOST and not start.get("token")
                        and start.get("lookback")):
                    return iter([]), self._oldest_available_start(cfg, start, flow)
                if exc.code in (CHANGE_STREAM_HISTORY_LOST, CHANGE_STREAM_FATAL_ERROR):
                    raise RuntimeError(
                        f"The change stream position of {cfg.namespace} ({flow} flow) is no longer in "
                        "the oplog (the pipeline was stopped longer than the oplog window). Run a full "
                        "refresh of this table to take a new snapshot, and consider a larger oplog."
                    ) from exc
                raise
            except (InvalidBSON, UnicodeDecodeError) as exc:
                raise self._decode_error(cfg, exc) from exc

            if end is not None:
                return iter(rows), end
            if last_token is not None:
                return iter(rows), self._offset(cfg, "stream", last_token)

            # Nothing new up to the cap. Move the cap forward for the next trigger
            # (continuous mode) and report "no more data" for this one.
            self._caps[cap_key] = self._now()
            if not (drained and pbrt):
                return iter([]), start
            if not start.get("token"):
                # A position given as a time is turned into a token once it is read.
                return iter([]), self._offset(cfg, "stream", pbrt, at=self._caps[cap_key].time,
                                              idle=True)
            # On an idle collection, move the stored token forward now and then so
            # that a long pause does not leave it behind the oplog window. Never
            # twice in a row: the second empty poll must end Trigger.AvailableNow.
            idle_for = self._caps[cap_key].time - start.get("at", 0)
            if (cfg.idle_advance and not start.get("idle") and pbrt > start["token"]
                    and idle_for >= cfg.idle_advance):
                return iter([]), self._offset(cfg, "stream", pbrt, at=self._caps[cap_key].time,
                                              idle=True)
            return iter([]), start

        def _oldest_available_start(self, cfg: _TableConfig, start: dict, flow: str) -> dict:
            """The look-back start is older than the oplog: find the oldest start that works.

            Jumping to "now" would skip deletes that are still in the oplog, so the
            oldest readable time is found by bisection between the failed start
            and now (to within ``MIN_LOOKBACK_SECONDS``).
            """
            import pymongo.errors  # pylint: disable=import-outside-toplevel

            low, high = int(start["start_at"]), self._now().time
            while high - low > MIN_LOOKBACK_SECONDS:
                mid = (low + high) // 2
                try:
                    with self._collection(cfg).watch(start_at_operation_time=Timestamp(mid, 0),
                                                     pipeline=[{"$match": {"_lakeflow_never": True}}],
                                                     max_await_time_ms=1) as stream:
                        stream.try_next()
                    high = mid
                except pymongo.errors.OperationFailure as exc:
                    if exc.code != CHANGE_STREAM_HISTORY_LOST:
                        raise
                    low = mid
            if self._now().time - high < MIN_LOOKBACK_SECONDS:
                raise RuntimeError(
                    f"The oplog of {cfg.namespace} does not reach back even {MIN_LOOKBACK_SECONDS} "
                    f"seconds, so the {flow} flow cannot start without missing changes."
                )
            return self._offset(cfg, "stream", None, start_at=high)

        @staticmethod
        def _raise_if_terminal(cfg: _TableConfig, event: dict) -> None:
            op = event.get("operationType")
            if op in TERMINAL_EVENTS:
                raise RuntimeError(
                    f"The change stream of {cfg.namespace} ended with a '{op}' event (the collection "
                    "was dropped or renamed). Run a full refresh after the collection is recreated."
                )

        def _change_row(self, cfg: _TableConfig, event: dict, flow: str) -> Optional[dict]:
            op = event["operationType"]
            key = event.get("documentKey") or {}
            if "_id" not in key:
                return None
            document = None
            if op != "delete":
                full = event.get("fullDocument")
                if full is None and cfg.full_document != "updateLookup" and flow == "upsert":
                    # whenAvailable: the post-image can be missing (for example expired
                    # by expireAfterSeconds). Fall back to the current document rather
                    # than dropping the change; `required` makes the server fail instead.
                    full = self._collection(cfg).find_one({"_id": key["_id"]})
                if full is not None:
                    document = dumps(full)
                elif cfg.ingestion_type != "append":
                    # updateLookup found nothing: the document was deleted after this
                    # update. The delete event that follows removes the row.
                    return None
                # In append mode the event is kept as a change-log entry; the
                # document is null because it no longer exists.
            return {
                "_id": encode_id(key["_id"]),
                "document": document if flow == "upsert" else None,
                "_cdc_operation": op,
                "_cdc_sequence": token_data(event["_id"]),
                "_cdc_cluster_time": timestamp_to_datetime(event.get("clusterTime")),
                "_cdc_wall_time": to_utc(event.get("wallTime")),
                "_cdc_namespace": cfg.namespace,
            }

        def _guard_decode(self, cfg: _TableConfig, fn):
            try:
                return fn()
            except (InvalidBSON, UnicodeDecodeError) as exc:
                raise self._decode_error(cfg, exc) from exc

        @staticmethod
        def _decode_error(cfg: _TableConfig, exc: Exception) -> RuntimeError:
            return RuntimeError(
                f"A document in {cfg.namespace} contains a string that is not valid UTF-8 ({exc}). "
                "Fix the data, or set the connection parameter unicode_decode_error_handler=replace "
                "to ingest it with U+FFFD replacement characters."
            )


    ########################################################
    # src/databricks/labs/community_connector/sparkpds/lakeflow_datasource.py
    ########################################################

    LakeflowConnectImpl = MongodbLakeflowConnect
    # Constant option or column names
    METADATA_TABLE = "_community_table_metadata"
    NAMESPACES_TABLE = "_community_namespaces"
    TABLES_TABLE = "_community_tables"
    VIRTUAL_TABLES = (METADATA_TABLE, NAMESPACES_TABLE, TABLES_TABLE)
    TABLE_NAME = "tableName"
    TABLE_NAME_LIST = "tableNameList"
    TABLE_CONFIGS = "tableConfigs"
    IS_DELETE_FLOW = "isDeleteFlow"
    NAMESPACE_PREFIX = "namespacePrefix"
    NAMESPACE = "namespace"


    def _decode_list_of_str_option(option_name: str, value: str | None) -> list[str] | None:
        """Decode and validate a JSON-encoded ``list[str]`` Spark option.

        Returns ``None`` if the option is absent; otherwise the parsed list.
        Raises ``ValueError`` with the offending value if the JSON is malformed
        or the decoded value is not a list of strings.
        """
        if value is None:
            return None
        try:
            decoded = json.loads(value)
        except json.JSONDecodeError as e:
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded list[str]; "
                f"got non-JSON value: {value!r}"
            ) from e
        if not isinstance(decoded, list) or not all(isinstance(s, str) for s in decoded):
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded list[str]; "
                f"got: {decoded!r}"
            )
        return decoded


    def _decode_dict_option(option_name: str, value: str | None) -> dict:
        """Decode and validate a JSON-encoded ``dict`` Spark option."""
        if value is None:
            return {}
        try:
            decoded = json.loads(value)
        except json.JSONDecodeError as e:
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded dict; "
                f"got non-JSON value: {value!r}"
            ) from e
        if not isinstance(decoded, dict):
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded dict; got: {decoded!r}"
            )
        return decoded


    # PySpark's DataSource API requires camelCase method names and inherits
    # semantics from the parent class, so per-method docstrings are redundant.
    # pylint: disable=invalid-name,missing-function-docstring
    class LakeflowStreamReader(SimpleDataSourceStreamReader, SupportsTriggerAvailableNow):
        """
        Implements a data source stream reader for Lakeflow Connect.
        Currently, only the simpleStreamReader is implemented, which uses a
        more generic protocol suitable for most data sources that support
        incremental loading.
        """

        def __init__(
            self,
            options: dict[str, str],
            schema: StructType,
            lakeflow_connect: LakeflowConnect,
        ):
            self.options = options
            self.lakeflow_connect = lakeflow_connect
            self.schema = schema

        def initialOffset(self):
            return {}

        def read(self, start: dict) -> (Iterator[tuple], dict):
            is_delete_flow = self.options.get(IS_DELETE_FLOW) == "true"
            # Strip delete flow options before passing to connector
            table_options = {
                k: v for k, v in self.options.items() if k != IS_DELETE_FLOW
            }

            if is_delete_flow:
                records, offset = self.lakeflow_connect.read_table_deletes(
                    self.options[TABLE_NAME], start, table_options
                )
            else:
                records, offset = self.lakeflow_connect.read_table(
                    self.options[TABLE_NAME], start, table_options
                )
            rows = map(lambda x: parse_value(x, self.schema), records)
            return rows, offset

        def readBetweenOffsets(self, start: dict, end: dict) -> Iterator[tuple]:
            # TODO: This does not ensure the records returned are identical across repeated calls.
            # For append-only tables, the data source must guarantee that reading from the same
            # start offset will always yield the same set of records.
            # For tables ingested as incremental CDC, it is only necessary that no new changes
            # are missed in the returned records.
            return self.read(start)[0]

        def prepareForTriggerAvailableNow(self) -> None:
            # No need to do anything special here. Everything is handled in the __init__ method.
            pass


    class LakeflowPartitionedStreamReader(DataSourceStreamReader, SupportsTriggerAvailableNow):
        """Proxy that bridges SupportsPartitionedStream to PySpark's DataSourceStreamReader.

        Used when a connector implements the SupportsPartitionedStream mixin to
        support partitioned streaming reads across Spark executors.
        """

        def __init__(
            self,
            options: dict[str, str],
            schema: StructType,
            lakeflow_connect: LakeflowConnect,
        ):
            self.options = options
            self.schema = schema
            self.lakeflow_connect = lakeflow_connect
            self.table_name = options[TABLE_NAME]
            self.table_options = {k: v for k, v in options.items() if k != IS_DELETE_FLOW}

        def initialOffset(self):
            return {}

        def getDefaultReadLimit(self):
            # Admission control is the connector's responsibility (e.g. via
            # window_days, max_records_per_batch), not the engine's.  Always
            # ask the engine for ReadAllAvailable.
            return ReadAllAvailable()

        def latestOffset(self, start: dict, limit) -> dict:
            # We declared ReadAllAvailable via getDefaultReadLimit; the engine
            # must respect it.  Anything else means admission-control expectations
            # we do not support — fail loudly rather than silently ignore.
            if not isinstance(limit, ReadAllAvailable):
                raise ValueError(
                    f"LakeflowPartitionedStreamReader only supports ReadAllAvailable; "
                    f"got {type(limit).__name__}. Micro-batch sizing must be controlled "
                    f"by the connector implementation (table_options), not the engine."
                )
            return self.lakeflow_connect.latest_offset(
                self.table_name, self.table_options, start
            )

        def partitions(self, start: dict, end: dict):
            partition_descs = self.lakeflow_connect.get_partitions(
                self.table_name, self.table_options, start, end
            )
            return [InputPartition(json.dumps(p)) for p in partition_descs]

        def read(self, partition: InputPartition):
            partition_desc = json.loads(partition.value)
            records = self.lakeflow_connect.read_partition(
                self.table_name, partition_desc, self.table_options
            )
            return map(lambda x: parse_value(x, self.schema), records)

        def prepareForTriggerAvailableNow(self) -> None:
            # No need to do anything special here. Everything is handled in the __init__ method.
            pass


    class LakeflowBatchReader(DataSourceReader):
        def __init__(
            self,
            options: dict[str, str],
            schema: StructType,
            lakeflow_connect: LakeflowConnect,
        ):
            self.options = options
            self.schema = schema
            self.lakeflow_connect = lakeflow_connect
            self.table_name = options[TABLE_NAME]
            self._supports_partition = isinstance(lakeflow_connect, SupportsPartition)

        def partitions(self):
            if self._supports_partition and self.table_name not in VIRTUAL_TABLES:
                try:
                    partition_descs = self.lakeflow_connect.get_partitions(
                        self.table_name, self.options
                    )
                    return [InputPartition(json.dumps(p)) for p in partition_descs]
                except Exception:
                    self._supports_partition = False
            return [InputPartition(None)]

        def read(self, partition):
            if self.table_name == METADATA_TABLE:
                records = self._read_table_metadata()
            elif self.table_name == NAMESPACES_TABLE:
                records = self._read_namespaces()
            elif self.table_name == TABLES_TABLE:
                records = self._read_tables()
            elif self._supports_partition and partition.value is not None:
                partition_desc = json.loads(partition.value)
                records = self.lakeflow_connect.read_partition(
                    self.table_name, partition_desc, self.options
                )
            else:
                records, _ = self.lakeflow_connect.read_table(self.table_name, None, self.options)
            return map(lambda x: parse_value(x, self.schema), records)

        def _read_table_metadata(self):
            table_names = _decode_list_of_str_option(
                TABLE_NAME_LIST, self.options.get(TABLE_NAME_LIST)
            ) or []
            table_configs = _decode_dict_option(
                TABLE_CONFIGS, self.options.get(TABLE_CONFIGS)
            )
            all_records = []
            # Preserve caller-supplied table order — caller controls it.
            for table in table_names:
                metadata = self.lakeflow_connect.read_table_metadata(
                    table, table_configs.get(table, {})
                )
                all_records.append({TABLE_NAME: table, **metadata})
            return all_records

        def _read_namespaces(self):
            # Connectors without SupportsNamespaces are flat — no rows.
            if not isinstance(self.lakeflow_connect, SupportsNamespaces):
                return []
            prefix = _decode_list_of_str_option(
                NAMESPACE_PREFIX, self.options.get(NAMESPACE_PREFIX)
            )
            namespaces = self.lakeflow_connect.list_namespaces(prefix)
            # Sort framework-side for deterministic output regardless of
            # connector iteration order.
            return [{"namespace": ns} for ns in sorted(namespaces)]

        def _read_tables(self):
            namespace_supplied = NAMESPACE in self.options
            if isinstance(self.lakeflow_connect, SupportsNamespaces):
                if not namespace_supplied:
                    raise ValueError(
                        f"option '{NAMESPACE}' is required when reading "
                        f"'{TABLES_TABLE}' against a connector that implements "
                        f"SupportsNamespaces. Pass a JSON-encoded list[str] "
                        f"(use '[]' for root-level tables; walk the tree via "
                        f"'{NAMESPACES_TABLE}' to enumerate every namespace)."
                    )
                namespace = _decode_list_of_str_option(
                    NAMESPACE, self.options[NAMESPACE]
                )
                tables = self.lakeflow_connect.list_tables_in_namespace(namespace)
                return [
                    {"namespace": namespace, TABLE_NAME: tn}
                    for tn in sorted(tables)
                ]
            # Flat connector path. Reject a stray `namespace` option — the
            # caller probably mistook this connector for namespace-aware and
            # silently ignoring the option would mask the bug.
            if namespace_supplied:
                raise ValueError(
                    f"option '{NAMESPACE}' was supplied but the connector does "
                    f"not implement SupportsNamespaces. Either omit the option "
                    f"or use a namespace-aware connector."
                )
            return [
                {"namespace": [], TABLE_NAME: tn}
                for tn in sorted(self.lakeflow_connect.list_tables())
            ]


    class LakeflowSource(DataSource):
        """
        PySpark DataSource base for Lakeflow Connect.

        Two ways the connector implementation is bound:

        - Per-source subclass (wheel / multi-file deployment): subclass and set
          ``_lakeflow_connect_cls``::

              class GmailDataSource(LakeflowSource):
                  _lakeflow_connect_cls = GmailLakeflowConnect

              spark.dataSource.register(GmailDataSource)

        - Merged single-file deployment (SDP): ``_lakeflow_connect_cls`` is left
          ``None`` and the connector is taken from the module-level
          ``LakeflowConnectImpl`` placeholder, which the merge script substitutes
          with the actual implementation class.
        """

        # Per-source subclasses set this. Left ``None`` on the base so the merged
        # single-file path falls back to the ``LakeflowConnectImpl`` placeholder.
        _lakeflow_connect_cls = None

        # Spark format name. Defaults to "lakeflow_connect" because Unity Catalog
        # connection-option injection looks for that exact string. A per-source
        # subclass may override this with its source name once it no longer relies
        # on UC injection (see the commented override in each source's __init__.py).
        _format_name = "lakeflow_connect"

        def __init__(self, options):
            self.options = options
            table = options.get(TABLE_NAME)
            # Catch typos against the framework's reserved virtual-table namespace
            # early — falling through to the connector with an unknown
            # `_community_*` name yields a confusing per-connector error.
            if table and table.startswith("_community_") and table not in VIRTUAL_TABLES:
                raise ValueError(
                    f"unknown framework virtual table '{table}'. Valid framework "
                    f"virtual tables are: {', '.join(VIRTUAL_TABLES)}. "
                    f"For a regular source table, use a name that does not start "
                    f"with '_community_'."
                )
            # Per-source subclasses bind the implementation via _lakeflow_connect_cls.
            # The merged single-file path leaves it None and relies on the
            # LakeflowConnectImpl placeholder (substituted by the merge script).
            connect_cls = type(self)._lakeflow_connect_cls or LakeflowConnectImpl
            self.lakeflow_connect = connect_cls(options)  # pylint: disable=abstract-class-instantiated

        @classmethod
        def name(cls):
            return cls._format_name

        def schema(self):
            table = self.options[TABLE_NAME]
            if table == METADATA_TABLE:
                return StructType(
                    [
                        StructField(TABLE_NAME, StringType(), False),
                        StructField("primary_keys", ArrayType(StringType()), True),
                        StructField("cursor_field", StringType(), True),
                        StructField("ingestion_type", StringType(), True),
                    ]
                )
            if table == NAMESPACES_TABLE:
                return StructType(
                    [
                        StructField("namespace", ArrayType(StringType()), False),
                    ]
                )
            if table == TABLES_TABLE:
                return StructType(
                    [
                        StructField("namespace", ArrayType(StringType()), False),
                        StructField(TABLE_NAME, StringType(), False),
                    ]
                )
            return self.lakeflow_connect.get_table_schema(table, self.options)

        def reader(self, schema: StructType):
            return LakeflowBatchReader(self.options, schema, self.lakeflow_connect)

        def streamReader(self, schema: StructType):
            # Use the partitioned DataSourceStreamReader when the connector
            # implements SupportsPartitionedStream and the table opts in.
            # Otherwise, delegate to super() which raises PySparkNotImplementedError,
            # causing Spark to fall back to simpleStreamReader().
            if isinstance(self.lakeflow_connect, SupportsPartitionedStream):
                table = self.options[TABLE_NAME]
                if self.lakeflow_connect.is_partitioned(table):
                    return LakeflowPartitionedStreamReader(self.options, schema, self.lakeflow_connect)
            return super().streamReader(schema)

        def simpleStreamReader(self, schema: StructType):
            return LakeflowStreamReader(self.options, schema, self.lakeflow_connect)


    spark.dataSource.register(LakeflowSource)
